{
  "findings": [
    {
      "check_id": "CKV_AWS_8",
      "title": "Ensure all data stored in the Launch configuration or instance Elastic Blocks Store is securely encrypted",
      "resource": "aws_instance.ubuntu[2]",
      "severity": "MEDIUM",
      "explanation": "The EC2 instance does not have encryption enabled for its Elastic Block Store (EBS) volumes."
    },
    {
      "check_id": "CKV_AWS_88",
      "title": "EC2 instance should not have public IP.",
      "resource": "aws_instance.ubuntu[1]",
      "severity": "MEDIUM",
      "explanation": "One of the EC2 instances is configured with a public IP address."
    },
    {
      "check_id": "CKV2_AWS_41",
      "title": "Ensure an IAM role is attached to EC2 instance",
      "resource": "aws_instance.ubuntu[2]",
      "severity": "MEDIUM",
      "explanation": "The EC2 instance does not have an IAM role attached."
    }
  ],
  "patched_code": "resource \"aws_instance\" \"ubuntu\" {\n  count = 3\n  ami = data.aws_ami.ubuntu_14_04.image_id\n  instance_type = \"t2.micro\"\n  associate_public_ip_address = ( count.index == 1 ? false : false)\n  subnet_id = aws_subnet.my_subnet.id\n  root_block_device {\n    encrypted = true\n  }\n  iam_instance_profile = aws_iam_instance_profile.example.name\n}",
  "fix_summary": "Disabled public IP for instance at index 1, enabled EBS encryption for all instances, and attached an IAM instance profile to all instances."
}
